#!/usr/bin/env python3
"""C15 run-dev-graph-schedule executor (R1-elicit / R2-plan / R3-schedule).

Read-only: asserts graph/tracker/lease digests are unchanged across the run.
Includes an independent C17 re-derivation that does not reuse schedule-graph.py.
"""
from __future__ import annotations

import hashlib
import json
import subprocess
import sys
from itertools import combinations
from pathlib import Path

PLUGIN_ROOT = Path("/Users/dm/orca/workspaces/harness/ジャーナル作成/plugins/dev-graph")


def digest_of(path: Path) -> str | None:
    return hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None


def c17_independent(graph: dict, leases: list[dict], max_parallel: int) -> dict:
    """Independent re-derivation of ready sets and safe batches from raw graph."""
    nodes = graph["nodes"]
    by_id = {n["graph_node_id"]: n for n in nodes}
    done = {i for i, n in by_id.items() if n["status"] in {"done", "closed"}}
    active_lease_ids = {l["graph_node_id"] for l in leases if l.get("state") not in {"released", "expired"}}
    active_lease_scopes = {s for l in leases if l.get("state") not in {"released", "expired"}
                           for s in l.get("resource_scope", [])}

    def eligible(node: dict) -> bool:
        return (
            node["status"] == "active"
            and node["confirmation_status"] == "confirmed"
            and node["evaluation_status"] == "pass"
            and node["implementation_readiness"]["status"] == "complete"
            and all(dep in done for dep in node["depends_on"])
            and node["graph_node_id"] not in active_lease_ids
            and not (set(node["resource_scope"]) & active_lease_scopes)
        )

    ready = sorted(i for i, n in by_id.items() if eligible(n))
    features = [i for i in ready if by_id[i]["artifact_kind"] == "feature"]
    tasks = [i for i in ready if by_id[i]["artifact_kind"] != "feature"]

    def pack(ids: list[str]) -> list[list[str]]:
        batches: list[list[str]] = []
        for node_id in ids:
            scope = set(by_id[node_id]["resource_scope"])
            for batch in batches:
                if len(batch) >= max_parallel:
                    continue
                occupied = {s for x in batch for s in by_id[x]["resource_scope"]}
                if not scope & occupied:
                    batch.append(node_id)
                    break
            else:
                batches.append([node_id])
        return batches

    return {"ready_features": features, "ready_tasks": tasks,
            "feature_batches": pack(features), "task_batches": pack(tasks)}


def split_by_max_parallel(batches: list[list[str]], max_parallel: int) -> list[list[str]]:
    result: list[list[str]] = []
    for batch in batches:
        for start in range(0, len(batch), max_parallel):
            result.append(batch[start:start + max_parallel])
    return result


def main() -> int:
    repo_root_arg, max_parallel = sys.argv[1], int(sys.argv[2])
    if max_parallel < 1:
        raise SystemExit("max_parallel must be a positive integer")

    # --- R1-elicit: C24 read receipt fixes DEV_GRAPH_ROOT ---------------------
    ctx = json.loads(subprocess.run(
        [sys.executable, str(PLUGIN_ROOT / "scripts" / "resolve-repo-context.py"),
         "--repo-root", repo_root_arg, "--mode", "read"],
        check=True, capture_output=True, text=True).stdout)
    root = Path(ctx["repo_root"]).resolve(strict=True)
    if Path(ctx["content_roots"]["repository"]).resolve(strict=True) != root:
        raise SystemExit("repo_root mismatch: fail-closed")

    graph_path = root / ".dev-graph" / "state" / "graph.json"
    leases_path = Path(ctx["coordination_paths"]["leases"])
    events_path = Path(ctx["coordination_paths"]["events"])
    config_path = root / ".dev-graph" / "config.json"

    before = {"graph": digest_of(graph_path), "leases": digest_of(leases_path),
              "events": digest_of(events_path), "config": digest_of(config_path)}

    graph = json.loads(graph_path.read_text("utf-8"))
    config = json.loads(config_path.read_text("utf-8"))

    # --- R2-plan: binding split decides the ready source ---------------------
    bindings = sorted({n["tracker_binding"] for n in graph["nodes"]})
    if bindings != ["none"]:
        raise SystemExit(f"mixed tracker bindings need per-binding ready sources: {bindings}")
    ready_source = "self"  # github/none -> C16 local computation

    leases_raw = json.loads(leases_path.read_text("utf-8")) if leases_path.is_file() else {"leases": []}
    leases = leases_raw.get("leases", []) if isinstance(leases_raw, dict) else leases_raw

    # --- R3-schedule: canonical computation ---------------------------------
    argv = [sys.executable, str(PLUGIN_ROOT / "scripts" / "schedule-graph.py"),
            "--graph", str(graph_path), "--ready-source", ready_source]
    if leases_path.is_file():
        argv += ["--leases", str(leases_path)]
    proc = subprocess.run(argv, capture_output=True, text=True)
    if proc.returncode != 0:
        raise SystemExit(f"schedule-graph.py failed: {proc.stderr.strip()}")
    schedule = json.loads(proc.stdout)

    feature_batches = split_by_max_parallel(schedule["batches"]["features"], max_parallel)
    task_batches = split_by_max_parallel(schedule["batches"]["tasks"], max_parallel)

    # --- C17 independent verifier -------------------------------------------
    independent = c17_independent(graph, leases, max_parallel)
    by_id = {n["graph_node_id"]: n for n in graph["nodes"]}

    findings: list[str] = []
    if sorted(schedule["ready_set"]["features"]) != independent["ready_features"]:
        findings.append("feature ready-set mismatch with independent recomputation")
    if sorted(schedule["ready_set"]["tasks"]) != independent["ready_tasks"]:
        findings.append("task ready-set mismatch with independent recomputation")
    if sorted(map(sorted, task_batches)) != sorted(map(sorted, independent["task_batches"])):
        findings.append("task batch partition mismatch with independent recomputation")
    if sorted(map(sorted, feature_batches)) != sorted(map(sorted, independent["feature_batches"])):
        findings.append("feature batch partition mismatch with independent recomputation")

    # --- acceptance evidence -------------------------------------------------
    ready_tasks = schedule["ready_set"]["tasks"]
    ready_features = schedule["ready_set"]["features"]
    done_ids = {i for i, n in by_id.items() if n["status"] in {"done", "closed"}}

    disqualified = [
        i for i in ready_tasks + ready_features
        if by_id[i]["status"] != "active"
        or by_id[i]["confirmation_status"] != "confirmed"
        or by_id[i]["evaluation_status"] != "pass"
        or by_id[i]["implementation_readiness"]["status"] != "complete"
    ]
    unmet = [i for i in ready_tasks + ready_features
             if any(dep not in done_ids for dep in by_id[i]["depends_on"])]

    overlaps = []
    for batch in feature_batches + task_batches:
        for left, right in combinations(batch, 2):
            shared = sorted(set(by_id[left]["resource_scope"]) & set(by_id[right]["resource_scope"]))
            if shared:
                overlaps.append({"pair": [left, right], "shared_resource_scope": shared})

    oversized = [b for b in feature_batches + task_batches if len(b) > max_parallel]
    mixed = [b for b in task_batches if any(by_id[i]["artifact_kind"] == "feature" for i in b)]
    mixed += [b for b in feature_batches if any(by_id[i]["artifact_kind"] != "feature" for i in b)]

    hints = {h["graph_node_id"]: h for h in schedule["assignment_hints"]}
    hint_findings = []
    for node_id in ready_tasks:
        hint = hints.get(node_id)
        if not hint:
            hint_findings.append(f"{node_id}: missing assignment hint")
            continue
        if hint["suggested_branch"] != f"devgraph/{node_id}":
            hint_findings.append(f"{node_id}: non-canonical suggested_branch")
        if not hint["claim_command"].startswith(f"/dev-graph worktree claim {node_id} --branch devgraph/{node_id}"):
            hint_findings.append(f"{node_id}: claim command is not the public CLI form")
    branches = [h["suggested_branch"] for h in schedule["assignment_hints"]]
    commands = [h["claim_command"] for h in schedule["assignment_hints"]]
    if len(set(branches)) != len(branches):
        hint_findings.append("suggested_branch values are not unique")
    if len(set(commands)) != len(commands):
        hint_findings.append("claim commands are not unique")
    if set(hints) != set(ready_tasks):
        hint_findings.append("assignment hints do not cover exactly the ready task set")

    after = {"graph": digest_of(graph_path), "leases": digest_of(leases_path),
             "events": digest_of(events_path), "config": digest_of(config_path)}
    read_only = before == after

    excluded = {}
    for node_id, node in by_id.items():
        if node_id in ready_tasks or node_id in ready_features:
            continue
        reasons = []
        if node["status"] in {"done", "closed"}:
            reasons.append(f"status={node['status']}")
        if node["status"] == "blocked":
            reasons.append("status=blocked")
        if node["status"] == "draft":
            reasons.append("status=draft")
        if node["confirmation_status"] != "confirmed":
            reasons.append(f"confirmation_status={node['confirmation_status']}")
        if node["evaluation_status"] != "pass":
            reasons.append(f"evaluation_status={node['evaluation_status']}")
        if node["implementation_readiness"]["status"] != "complete":
            reasons.append(f"implementation_readiness={node['implementation_readiness']['status']}")
        unmet_deps = [d for d in node["depends_on"] if d not in done_ids]
        if unmet_deps:
            reasons.append(f"unmet_depends_on={unmet_deps}")
        excluded[node_id] = reasons

    checks = {
        "IN1_no_ineligible_in_ready_set": not disqualified,
        "OUT1_all_dependencies_done": not unmet,
        "OUT2_no_resource_scope_overlap_in_batch": not overlaps,
        "OUT3_unique_canonical_branch_and_claim": not hint_findings,
        "feature_task_ready_sets_separated": not mixed,
        "max_parallel_respected": not oversized,
        "c17_independent_agreement": not findings,
        "read_only_digest_stable": read_only,
    }

    report = {
        "skill": "run-dev-graph-schedule",
        "scope": "whole-graph",
        "max_parallel": max_parallel,
        "ready_source": schedule["ready_source"],
        "tracker_bindings": bindings,
        "graph_revision": graph["graph_revision"],
        "execution_tracker_mode": config["execution_tracker"]["mode"],
        "ready_set": {"features": ready_features, "tasks": ready_tasks},
        "batches": {"features": feature_batches, "tasks": task_batches},
        "raw_batches_before_max_parallel": schedule["batches"],
        "conflicts": schedule["conflicts"],
        "active_leases": leases,
        "assignment_hints": schedule["assignment_hints"],
        "excluded_nodes": excluded,
        "resource_scope_overlaps": overlaps,
        "disqualified_candidates": disqualified,
        "unmet_dependency_candidates": unmet,
        "hint_findings": hint_findings,
        "c17_independent_verifier": {"findings": findings, **independent},
        "digests_before": before,
        "digests_after": after,
        "checks": checks,
        "verdict": "PASS" if all(checks.values()) else "FAIL",
    }
    print(json.dumps(report, ensure_ascii=False, indent=2))
    return 0 if report["verdict"] == "PASS" else 1


if __name__ == "__main__":
    raise SystemExit(main())

