            if set(by_id[left]["resource_scope"]) & set(by_id[right]["resource_scope"]):
                findings.append(f"{label} batch has a resource_scope overlap: {left}/{right}")
    if len(proposed) > len(independent[f"{label}_batches"]):
        findings.append(f"{label} batch count is worse than the independent packing")

